/**
 * Event pages, keyed by event title (lib/listings.ts slugs them and takes each card's location and date from here).
 * `location` is the venue: it leads the header and every card (`location | date`).
 */
type EventDraft = {
  title: string; location: string; date: string; hero: string; sub: string;
  about: string[]; programme: string[]; callout: Block; setting: { h: string; p: string[] };
  img: [string, string]; img2: [string, string]; attend?: string[]; past?: boolean;
};
const ATTEND = ["Places are limited. Register your interest on this site or call 16922 and the events team will confirm your invitation and the final timings.",
  "Timings may change as the date approaches; registered guests will be the first to know."];
const NEXT = ["More moments like this are planned through the year. See the Events page for what is coming next, or register your interest to hear first."];

const event = (e: EventDraft): Written => ({
  tag: e.location, date: e.date, title: e.title, sub: e.sub, hero: e.hero,
  body: [
    { img: e.img[0], caption: e.img[1] },
    ...ps(...e.about),
    { h: e.past ? "What happened" : "The programme" },
    { list: e.programme },
    e.callout,
    { img: e.img2[0], caption: e.img2[1] },
    { h: e.setting.h },
    ...ps(...e.setting.p),
    { h: e.past ? "What comes next" : "How to attend" },
    ...ps(...(e.attend ?? (e.past ? NEXT : ATTEND))),
  ],
});

